{
  "name": "a4s-context-expert",
  "version": "0.3.2",
  "description": "Jev-guided deterministic compaction for Claude Code with the shared adaptive trigger policy and keep/truncate/drop transcript selection.",
  "license": "UNLICENSED",
  "author": {
    "name": "pablontiv"
  },
  "userConfig": {
    "apiKey": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "TypeSafe API key for Jev. Leave unset to use TYPESAFE_API_KEY.",
      "sensitive": true
    },
    "keepThreshold": {
      "type": "number",
      "title": "Keep threshold",
      "description": "Minimum Jev probability that a tool call or result is still needed; below it the item is removed.",
      "default": 0.5
    },
    "preserveRecentMessages": {
      "type": "number",
      "title": "Recent messages to preserve",
      "description": "Number of newest messages pinned from compaction (the first message is always kept).",
      "default": 6
    },
    "triggerMode": {
      "type": "string",
      "title": "Auto-compact trigger mode",
      "description": "off | hint | auto. 'hint' asks the user to run /compact and does not compact. 'auto' compacts after a positive shared-policy decision. 'off' disables the trigger.",
      "default": "auto"
    },
    "minimumContextRatio": {
      "type": "number",
      "title": "Legacy minimum context ratio",
      "description": "Validated compatibility setting. The shared adaptive policy computes its token floor and ceiling from the model context window.",
      "default": 0.5
    },
    "minReductionRatio": {
      "type": "number",
      "title": "Minimum reduction ratio",
      "description": "Minimum estimated character reduction required to replace history; below it, fall back to the native summary.",
      "default": 0.25
    },
    "maxStateTokens": {
      "type": "number",
      "title": "Maximum Jev state tokens",
      "description": "Estimated token budget for the conversation state sent with every Jev request.",
      "default": 25000
    },
    "maxRequestTokens": {
      "type": "number",
      "title": "Maximum Jev request tokens",
      "description": "Estimated token budget for state plus questions in one Jev request.",
      "default": 30000
    },
    "truncateHeadChars": {
      "type": "number",
      "title": "Truncated tool result head",
      "description": "Characters of a tool result kept when Jev decides its full output is no longer needed; 0 keeps only the note.",
      "default": 300
    },
    "model": {
      "type": "string",
      "title": "Jev model",
      "description": "TypeSafe Jev model name.",
      "default": "jev-latest"
    }
  }
}
